class Solution:
    def minAbsDifference(self, nums: List[int], goal: int) -> int:
        import bisect
        n = len(nums)
        half = n // 2
        def get_sums(arr):
            sums = {0}
            for x in arr:
                sums = sums | {s + x for s in sums}
            return sorted(sums)
        left = get_sums(nums[:half])
        right = get_sums(nums[half:])
        res = float('inf')
        for s in left:
            remain = goal - s
            idx = bisect.bisect_left(right, remain)
            if idx < len(right):
                res = min(res, abs(remain - right[idx]))
            if idx > 0:
                res = min(res, abs(remain - right[idx-1]))
        return res

