class Solution:
    def maximumScore(self, nums: List[int], multipliers: List[int]) -> int:
        m = len(multipliers)
        n = len(nums)
        dp = [[0] * (m + 1) for _ in range(m + 1)]
        for k in range(1, m + 1):
            for i in range(k + 1):
                j = k - i
                if j > n - i:
                    continue
                val = -float('inf')
                if i > 0:
                    val = max(val, dp[i-1][j] + nums[i-1] * multipliers[k-1])
                if j > 0:
                    val = max(val, dp[i][j-1] + nums[n-j] * multipliers[k-1])
                dp[i][j] = val
        return max(dp[i][m-i] for i in range(m+1) if m-i <= n-i)

