class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        self.ans = baseCosts[0]
        def dfs(idx, cur):
            if abs(cur - target) < abs(self.ans - target) or                (abs(cur - target) == abs(self.ans - target) and cur < self.ans):
                self.ans = cur
            if idx == len(toppingCosts) or cur > target:
                return
            dfs(idx + 1, cur)
            dfs(idx + 1, cur + toppingCosts[idx])
            dfs(idx + 1, cur + 2 * toppingCosts[idx])
        for base in baseCosts:
            dfs(0, base)
        return self.ans

class Solution:
    def minOperations(self, nums1: List[int], nums2: List[int]) -> int:
        s1, s2 = sum(nums1), sum(nums2)
        if s1 > s2:
            nums1, nums2 = nums2, nums1
            s1, s2 = s2, s1
        diff = s2 - s1
        if diff == 0:
            return 0
        gains = sorted([min(6, x) - max(1, x) for x in nums1] + [max(1, x) - min(6, x) for x in nums2], reverse=True)
        # Correction: gains from nums1 (increase) and nums2 (decrease)
        gains = []
        for x in nums1:
            gains.append(6 - x)
        for x in nums2:
            gains.append(x - 1)
        gains.sort(reverse=True)
        ops = 0
        for g in gains:
            if diff <= 0:
                return ops
            diff -= g
            ops += 1
        return ops if diff <= 0 else -1

class Solution:
    def getCollisionTimes(self, cars: List[List[int]]) -> List[float]:
        n = len(cars)
        ans = [-1.0] * n
        stack = []
        for i in range(n-1, -1, -1):
            pos, speed = cars[i]
            while stack:
                j = stack[-1]
                pj, sj = cars[j]
                if speed <= sj:
                    stack.pop()
                else:
                    t = (pj - pos) / (speed - sj)
                    if ans[j] < 0 or t <= ans[j]:
                        break
                    stack.pop()
            if stack:
                j = stack[-1]
                ans[i] = (cars[j][0] - pos) / (speed - cars[j][1])
            stack.append(i)
        return ans

