class Solution:
    def findShortestPath(self, master: 'GridMaster') -> int:
        dirs = {'U': (-1,0), 'D': (1,0), 'L': (0,-1), 'R': (0,1)}
        opposite = {'U':'D', 'D':'U', 'L':'R', 'R':'L'}
        grid = {(0,0): True}
        target = None
        def dfs(r, c):
            nonlocal target
            if master.isTarget():
                target = (r, c)
            for d, (dr, dc) in dirs.items():
                nr, nc = r+dr, c+dc
                if (nr,nc) not in grid:
                    if master.canMove(d):
                        master.move(d)
                        grid[(nr,nc)] = True
                        dfs(nr, nc)
                        master.move(opposite[d])
                    else:
                        grid[(nr,nc)] = False
        dfs(0, 0)
        if not target:
            return -1
        from collections import deque
        q = deque([(0, 0, 0)])
        visited = {(0,0)}
        while q:
            r, c, dist = q.popleft()
            if (r,c) == target:
                return dist
            for dr, dc in dirs.values():
                nr, nc = r+dr, c+dc
                if (nr,nc) in grid and grid[(nr,nc)] and (nr,nc) not in visited:
                    visited.add((nr,nc))
                    q.append((nr, nc, dist+1))
        return -1

