class Solution:
    def countPairs(self, n: int, edges: List[List[int]], queries: List[int]) -> List[int]:
        from collections import Counter
        degree = [0] * (n + 1)
        edge_cnt = Counter()
        for u, v in edges:
            degree[u] += 1
            degree[v] += 1
            edge_cnt[tuple(sorted((u, v)))] += 1
        sorted_deg = sorted(degree[1:])
        ans = []
        for q in queries:
            cnt = 0
            l, r = 0, n - 1
            while l < r:
                if sorted_deg[l] + sorted_deg[r] > q:
                    cnt += r - l
                    r -= 1
                else:
                    l += 1
            for (u, v), c in edge_cnt.items():
                if degree[u] + degree[v] > q and degree[u] + degree[v] - c <= q:
                    cnt -= 1
            ans.append(cnt)
        return ans

