class Solution:
    def countRestrictedPaths(self, n: int, edges: List[List[int]]) -> int:
        import heapq
        MOD = 10**9 + 7
        graph = [[] for _ in range(n + 1)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))
        dist = [float('inf')] * (n + 1)
        dist[n] = 0
        pq = [(0, n)]
        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue
            for v, w in graph[u]:
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
                    heapq.heappush(pq, (dist[v], v))
        dp = [0] * (n + 1)
        dp[n] = 1
        order = sorted(range(1, n+1), key=lambda x: dist[x])
        for u in order:
            for v, w in graph[u]:
                if dist[u] > dist[v]:
                    dp[u] = (dp[u] + dp[v]) % MOD
        return dp[1]

class Solution:
    def minChanges(self, nums: List[int], k: int) -> int:
        from collections import Counter
        n = len(nums)
        groups = [Counter() for _ in range(k)]
        size = [0] * k
        for i in range(n):
            groups[i % k][nums[i]] += 1
            size[i % k] += 1
        INF = float('inf')
        dp = [INF] * 1024
        dp[0] = 0
        for i in range(k):
            min_dp = min(dp)
            new_dp = [min_dp + size[i]] * 1024
            for mask in range(1024):
                if dp[mask] == INF:
                    continue
                for val, cnt in groups[i].items():
                    new_mask = mask ^ val
                    new_dp[new_mask] = min(new_dp[new_mask], dp[mask] + size[i] - cnt)
            dp = new_dp
        return dp[0]

class Solution:
    def maximumBeauty(self, flowers: List[int]) -> int:
        prefix = [0] * (len(flowers) + 1)
        for i, f in enumerate(flowers):
            prefix[i+1] = prefix[i] + max(0, f)
        first = {}
        ans = -float('inf')
        for i, f in enumerate(flowers):
            if f in first:
                j = first[f]
                beauty = prefix[i+1] - prefix[j] - max(0, flowers[j]) - max(0, flowers[i]) + flowers[j] + flowers[i]
                # Simplify: sum of positives between j and i, plus flowers[j] + flowers[i]
                beauty = prefix[i] - prefix[j+1] + flowers[j] + flowers[i]
                ans = max(ans, beauty)
            else:
                first[f] = i
        return ans

